Your expense tracker is below. Add an amount and a category, and the total and category split update as you go. Entries stay only while this page is open, so nothing is saved after you close it.

```page
<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8">
<style>
  body{font-family:system-ui,sans-serif;margin:0;padding:16px;background:#fafafa;color:#222}
  h2{margin:0 0 12px;font-size:18px}
  .row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}
  input,select,button{padding:8px;border:1px solid #ccc;border-radius:6px;font-size:14px}
  input{flex:1;min-width:100px}
  button{background:#0f6cbd;color:#fff;border:none;cursor:pointer}
  .card{background:#fff;border:1px solid #e3e3e3;border-radius:8px;padding:12px;margin-bottom:12px}
  .total{font-size:24px;font-weight:600}
  .bar{height:10px;background:#0f6cbd;border-radius:5px}
  .cat{margin:6px 0;font-size:13px}
  .item{display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid #eee;font-size:14px}
  .item small{color:#666}
  .del{background:none;color:#b00;padding:2px 6px}
  .empty{color:#777;font-size:13px}
</style>
</head>
<body>
<h2>Monthly expenses</h2>
<div class="card">
  <div class="row">
    <input id="desc" placeholder="What was it for?">
    <input id="amt" type="number" min="0" placeholder="Amount (₹)">
  </div>
  <div class="row">
    <select id="cat">
      <option>Food</option><option>Rent</option><option>Travel</option>
      <option>Bills</option><option>Shopping</option><option>Health</option><option>Other</option>
    </select>
    <input id="date" type="date">
    <button id="add">Add</button>
  </div>
</div>
<div class="card">
  <div>Total this month</div>
  <div class="total" id="total">₹0</div>
  <div class="row" style="margin:10px 0 0">
    <input id="budget" type="number" min="0" placeholder="Monthly budget (₹), optional">
  </div>
  <div id="left" class="cat"></div>
</div>
<div class="card"><div id="split"></div></div>
<div class="card"><div id="list"></div></div>
<script>
  var items = [];
  var $ = function(id){return document.getElementById(id)};
  var fmt = function(n){return '₹' + Number(n).toLocaleString('en-IN')};
  $('date').valueAsDate = new Date();
  function render(){
    var total = 0, by = {};
    items.forEach(function(i){total += i.amt; by[i.cat] = (by[i.cat]||0) + i.amt});
    $('total').textContent = fmt(total);
    var b = Number($('budget').value);
    $('left').textContent = b > 0 ? (b >= total ? fmt(b-total) + ' left of your budget' : fmt(total-b) + ' over your budget') : '';
    var s = '';
    Object.keys(by).sort(function(a,c){return by[c]-by[a]}).forEach(function(k){
      var p = Math.round(by[k]/total*100);
      s += '<div class="cat">' + k + ' · ' + fmt(by[k]) + ' (' + p + '%)<div class="bar" style="width:' + p + '%"></div></div>';
    });
    $('split').innerHTML = s || '<div class="empty">Your category split will show here.</div>';
    var l = '';
    items.forEach(function(i, idx){
      l += '<div class="item"><div>' + i.desc + '<br><small>' + i.cat + ' · ' + i.date + '</small></div><div>' + fmt(i.amt) + ' <button class="del" data-i="' + idx + '">✕</button></div></div>';
    });
    $('list').innerHTML = l || '<div class="empty">No expenses added yet.</div>';
  }
  $('add').onclick = function(){
    var a = Number($('amt').value);
    if(!(a > 0)) return;
    var d = $('desc').value.replace(/[<>&]/g,'') || $('cat').value;
    items.unshift({desc:d, amt:a, cat:$('cat').value, date:$('date').value});
    $('desc').value = ''; $('amt').value = '';
    render();
  };
  $('list').onclick = function(e){
    var i = e.target.getAttribute('data-i');
    if(i !== null){items.splice(Number(i),1); render();}
  };
  $('budget').oninput = render;
  render();
</script>
</body>
</html>
```
